"""IntervalSet: maintain a set of reals as a union of intervals with open/closed endpoints."""


class IntervalSet:
    def __init__(self):
        self._ivs = []

    @staticmethod
    def _left_key(lo, lo_closed):
        return (lo, 0 if lo_closed else 1)

    @staticmethod
    def _right_key(hi, hi_closed):
        return (hi, 0 if hi_closed else -1)

    @classmethod
    def _mergeable(cls, a, b):
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b
        if a_hi < b_lo:
            return False
        if a_hi > b_lo:
            return True
        return a_hc or b_lc

    @classmethod
    def _union_pair(cls, a, b):
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b
        lo = a_lo
        lo_closed = a_lc
        if b_lo < lo or (b_lo == lo and b_lc and not lo_closed):
            lo = b_lo
            lo_closed = b_lc
        if cls._right_key(b_hi, b_hc) > cls._right_key(a_hi, a_hc):
            hi = b_hi
            hi_closed = b_hc
        else:
            hi = a_hi
            hi_closed = a_hc
        return (lo, hi, lo_closed, hi_closed)

    @classmethod
    def _normalize(cls, ivs):
        cleaned = []
        for lo, hi, lc, hc in ivs:
            if lo > hi:
                continue
            if lo == hi and not (lc and hc):
                continue
            cleaned.append((lo, hi, lc, hc))
        cleaned.sort(key=lambda iv: (cls._left_key(iv[0], iv[2]),
                                     cls._right_key(iv[1], iv[3])))
        merged = []
        for iv in cleaned:
            if merged and cls._mergeable(merged[-1], iv):
                merged[-1] = cls._union_pair(merged[-1], iv)
            else:
                merged.append(iv)
        return merged

    def add(self, lo, hi, lo_closed, hi_closed):
        if lo == hi and not (lo_closed and hi_closed):
            return
        if lo > hi:
            return
        self._ivs = self._normalize(self._ivs + [(lo, hi, lo_closed, hi_closed)])

    def remove(self, lo, hi, lo_closed, hi_closed):
        if lo == hi and not (lo_closed and hi_closed):
            return
        if lo > hi:
            return
        result = []
        for iv in self._ivs:
            result.extend(self._subtract(iv, (lo, hi, lo_closed, hi_closed)))
        self._ivs = self._normalize(result)

    @classmethod
    def _subtract(cls, a, r):
        a_lo, a_hi, a_lc, a_hc = a
        r_lo, r_hi, r_lc, r_hc = r

        a_left = cls._left_key(a_lo, a_lc)
        a_right = cls._right_key(a_hi, a_hc)
        r_left = cls._left_key(r_lo, r_lc)
        r_right = cls._right_key(r_hi, r_hc)

        if r_right < a_left:
            return [a]
        if r_left > a_right:
            return [a]

        pieces = []

        if a_left < r_left:
            new_hi = r_lo
            new_hc = not r_lc
            pieces.append((a_lo, new_hi, a_lc, new_hc))

        if a_right > r_right:
            new_lo = r_hi
            new_lc = not r_hc
            pieces.append((new_lo, a_hi, new_lc, a_hc))

        valid = []
        for lo, hi, lc, hc in pieces:
            if lo > hi:
                continue
            if lo == hi and not (lc and hc):
                continue
            valid.append((lo, hi, lc, hc))
        return valid

    def contains(self, x):
        for lo, hi, lc, hc in self._ivs:
            if x < lo or x > hi:
                continue
            if x == lo and not lc:
                continue
            if x == hi and not hc:
                continue
            if lo < x < hi:
                return True
            if x == lo and lc:
                return True
            if x == hi and hc:
                return True
        return False

    def canonical(self):
        if not self._ivs:
            return "{}"
        parts = []
        for lo, hi, lc, hc in self._ivs:
            if lo == hi:
                parts.append("{" + format(lo, 'g') + "}")
            else:
                left = "[" if lc else "("
                right = "]" if hc else ")"
                parts.append(left + format(lo, 'g') + ", " + format(hi, 'g') + right)
        return " u ".join(parts)
