"""IntervalSet: a set of real numbers represented as a union of intervals."""


class IntervalSet:
    def __init__(self):
        self._intervals = []

    @staticmethod
    def _is_empty(lo, hi, lo_closed, hi_closed):
        if lo > hi:
            return True
        if lo == hi and not (lo_closed and hi_closed):
            return True
        return False

    @classmethod
    def _touch_or_overlap(cls, a, b):
        a_lo, a_hi, a_loc, a_hic = a
        b_lo, b_hi, b_loc, b_hic = b
        if a_hi < b_lo:
            return False
        if a_hi == b_lo and not (a_hic or b_loc):
            return False
        return True

    @classmethod
    def _union_pair(cls, a, b):
        a_lo, a_hi, a_loc, a_hic = a
        b_lo, b_hi, b_loc, b_hic = b
        if a_lo < b_lo:
            lo, lo_closed = a_lo, a_loc
        elif b_lo < a_lo:
            lo, lo_closed = b_lo, b_loc
        else:
            lo, lo_closed = a_lo, (a_loc or b_loc)
        if a_hi > b_hi:
            hi, hi_closed = a_hi, a_hic
        elif b_hi > a_hi:
            hi, hi_closed = b_hi, b_hic
        else:
            hi, hi_closed = a_hi, (a_hic or b_hic)
        return (lo, hi, lo_closed, hi_closed)

    def _normalize(self, intervals):
        items = [iv for iv in intervals if not self._is_empty(*iv)]
        items.sort(key=lambda iv: (iv[0], 0 if iv[2] else 1))
        merged = []
        for iv in items:
            if not merged:
                merged.append(iv)
                continue
            last = merged[-1]
            if self._touch_or_overlap(last, iv):
                merged[-1] = self._union_pair(last, iv)
            else:
                merged.append(iv)
        return merged

    def add(self, lo, hi, lo_closed, hi_closed):
        if self._is_empty(lo, hi, lo_closed, hi_closed):
            return
        self._intervals = self._normalize(
            self._intervals + [(lo, hi, lo_closed, hi_closed)]
        )

    def remove(self, lo, hi, lo_closed, hi_closed):
        if self._is_empty(lo, hi, lo_closed, hi_closed):
            return
        r = (lo, hi, lo_closed, hi_closed)
        result = []
        for iv in self._intervals:
            result.extend(self._subtract(iv, r))
        self._intervals = self._normalize(result)

    @staticmethod
    def _subtract(a, r):
        a_lo, a_hi, a_loc, a_hic = a
        r_lo, r_hi, r_loc, r_hic = r
        if a_hi < r_lo or (a_hi == r_lo and not (a_hic and r_loc)):
            return [a]
        if a_lo > r_hi or (a_lo == r_hi and not (a_loc and r_hic)):
            return [a]
        pieces = []
        if a_lo < r_lo or (a_lo == r_lo and a_loc and not r_loc):
            piece = (a_lo, r_lo, a_loc, not r_loc)
            if not IntervalSet._is_empty(*piece):
                pieces.append(piece)
        if a_hi > r_hi or (a_hi == r_hi and a_hic and not r_hic):
            piece = (r_hi, a_hi, not r_hic, a_hic)
            if not IntervalSet._is_empty(*piece):
                pieces.append(piece)
        return pieces

    def contains(self, x):
        for lo, hi, lo_closed, hi_closed in self._intervals:
            if x < lo or x > hi:
                continue
            if x == lo and not lo_closed:
                continue
            if x == hi and not hi_closed:
                continue
            return True
        return False

    def canonical(self):
        if not self._intervals:
            return "{}"
        parts = []
        for lo, hi, lo_closed, hi_closed in self._intervals:
            if lo == hi:
                parts.append("{" + format(lo, "g") + "}")
            else:
                left = "[" if lo_closed else "("
                right = "]" if hi_closed else ")"
                parts.append(
                    left + format(lo, "g") + ", " + format(hi, "g") + right
                )
        return " u ".join(parts)
