"""IntervalSet: a set of real numbers maintained as a union of intervals
with open or closed endpoints."""

_NEG_INF = float("-inf")
_POS_INF = float("inf")


def _valid(lo, hi, lo_closed, hi_closed):
    """Return True iff the interval is non-empty."""
    if lo < hi:
        return True
    if lo == hi:
        return lo_closed and hi_closed
    return False


def _intersect(a, b):
    """Intersect two generalized intervals (lo, hi, lo_closed, hi_closed).
    Return the resulting tuple or None if empty."""
    a_lo, a_hi, a_lc, a_hc = a
    b_lo, b_hi, b_lc, b_hc = b

    if a_lo > b_lo:
        lo, lc = a_lo, a_lc
    elif b_lo > a_lo:
        lo, lc = b_lo, b_lc
    else:
        lo, lc = a_lo, (a_lc and b_lc)

    if a_hi < b_hi:
        hi, hc = a_hi, a_hc
    elif b_hi < a_hi:
        hi, hc = b_hi, b_hc
    else:
        hi, hc = a_hi, (a_hc and b_hc)

    if _valid(lo, hi, lc, hc):
        return (lo, hi, lc, hc)
    return None


class IntervalSet:
    """A set of reals stored as sorted, disjoint, maximal intervals.

    Each stored interval is a tuple (lo, hi, lo_closed, hi_closed);
    a single point v is stored as (v, v, True, True).
    """

    def __init__(self):
        self._ivs = []

    def add(self, lo, hi, lo_closed, hi_closed):
        if not _valid(lo, hi, lo_closed, hi_closed):
            return
        ivs = self._ivs + [(lo, hi, lo_closed, hi_closed)]
        # Sort by lo; at equal lo a closed endpoint sorts first.
        ivs.sort(key=lambda iv: (iv[0], 0 if iv[2] else 1, iv[1]))
        merged = []
        for iv in ivs:
            if not merged:
                merged.append(iv)
                continue
            c_lo, c_hi, c_lc, c_hc = merged[-1]
            n_lo, n_hi, n_lc, n_hc = iv
            # Merge iff overlapping, or touching with at least one side closed.
            if n_lo < c_hi or (n_lo == c_hi and (c_hc or n_lc)):
                if n_hi > c_hi:
                    new_hi, new_hc = n_hi, n_hc
                elif n_hi < c_hi:
                    new_hi, new_hc = c_hi, c_hc
                else:
                    new_hi, new_hc = c_hi, (c_hc or n_hc)
                merged[-1] = (c_lo, new_hi, c_lc, new_hc)
            else:
                merged.append(iv)
        self._ivs = merged

    def remove(self, lo, hi, lo_closed, hi_closed):
        if not _valid(lo, hi, lo_closed, hi_closed):
            return
        # Complement of the removed region: two half-lines.
        left = (_NEG_INF, lo, False, not lo_closed)
        right = (hi, _POS_INF, not hi_closed, False)
        result = []
        for iv in self._ivs:
            piece = _intersect(iv, left)
            if piece is not None:
                result.append(piece)
            piece = _intersect(iv, right)
            if piece is not None:
                result.append(piece)
        self._ivs = result

    def contains(self, x):
        for lo, hi, lc, hc in self._ivs:
            if lo < x < hi:
                return True
            if x == lo and lc:
                return True
            if x == hi and hc:
                return True
        return False

    def canonical(self):
        if not self._ivs:
            return "{}"
        parts = []
        for lo, hi, lc, hc in self._ivs:
            if lo == hi:
                parts.append("{" + format(lo, "g") + "}")
            else:
                parts.append(
                    ("[" if lc else "(")
                    + format(lo, "g")
                    + ", "
                    + format(hi, "g")
                    + ("]" if hc else ")")
                )
        return " u ".join(parts)
