"""IntervalSet: a set of real numbers maintained as a union of intervals
with open or closed endpoints, kept in canonical (disjoint, sorted,
maximal) form."""


class IntervalSet:
    """A set of reals represented as a union of disjoint intervals.

    Each stored interval is a tuple (lo, hi, lo_closed, hi_closed).
    A single point {v} is stored as (v, v, True, True).
    The internal list is always canonical: disjoint, sorted, maximal.
    """

    def __init__(self):
        self._ivs = []

    # ------------------------------------------------------------------ #
    # helpers
    # ------------------------------------------------------------------ #

    @staticmethod
    def _valid(lo, hi, lo_closed, hi_closed):
        """True iff (lo, hi, lo_closed, hi_closed) denotes a nonempty set."""
        if lo < hi:
            return True
        if lo == hi:
            return lo_closed and hi_closed
        return False

    @staticmethod
    def _mergeable(a, b):
        """True iff the union of intervals a and b is a single interval
        (they overlap, or they touch at a point included by at least
        one side)."""
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b
        # a strictly separated below b?
        if a_hi < b_lo or (a_hi == b_lo and not (a_hc or b_lc)):
            return False
        # b strictly separated below a?
        if b_hi < a_lo or (b_hi == a_lo and not (b_hc or a_lc)):
            return False
        return True

    @staticmethod
    def _merge(a, b):
        """Union of two mergeable intervals as a single interval."""
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b
        if a_lo < b_lo:
            lo, lc = a_lo, a_lc
        elif b_lo < a_lo:
            lo, lc = b_lo, b_lc
        else:
            lo, lc = a_lo, (a_lc or b_lc)
        if a_hi > b_hi:
            hi, hc = a_hi, a_hc
        elif b_hi > a_hi:
            hi, hc = b_hi, b_hc
        else:
            hi, hc = a_hi, (a_hc or b_hc)
        return (lo, hi, lc, hc)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #

    def add(self, lo, hi, lo_closed, hi_closed):
        """Union the interval (lo, hi, lo_closed, hi_closed) into the set."""
        if not self._valid(lo, hi, lo_closed, hi_closed):
            return
        ivs = self._ivs + [(lo, hi, bool(lo_closed), bool(hi_closed))]
        # Sort by lower bound; a closed lower endpoint sorts before an
        # open one at the same value (it includes "more" on the left).
        ivs.sort(key=lambda t: (t[0], 0 if t[2] else 1))
        out = []
        for iv in ivs:
            if out and self._mergeable(out[-1], iv):
                out[-1] = self._merge(out[-1], iv)
            else:
                out.append(iv)
        self._ivs = out

    def remove(self, lo, hi, lo_closed, hi_closed):
        """Subtract the interval (lo, hi, lo_closed, hi_closed) from the set."""
        if not self._valid(lo, hi, lo_closed, hi_closed):
            return
        # The complement of the removed region R is
        #   C1 = (-inf, lo)  with right end closed iff R's lo is open
        #   C2 = (hi, +inf)  with left end closed iff R's hi is open
        # The new set is the union over stored A of (A & C1) and (A & C2).
        out = []
        for a_lo, a_hi, a_lc, a_hc in self._ivs:
            # left piece: A & C1  -> take min of upper bounds
            if a_hi < lo:
                l_hi, l_hc = a_hi, a_hc
            elif a_hi > lo:
                l_hi, l_hc = lo, (not lo_closed)
            else:
                l_hi, l_hc = a_hi, (a_hc and not lo_closed)
            if self._valid(a_lo, l_hi, a_lc, l_hc):
                out.append((a_lo, l_hi, a_lc, l_hc))
            # right piece: A & C2  -> take max of lower bounds
            if a_lo > hi:
                r_lo, r_lc = a_lo, a_lc
            elif a_lo < hi:
                r_lo, r_lc = hi, (not hi_closed)
            else:
                r_lo, r_lc = a_lo, (a_lc and not hi_closed)
            if self._valid(r_lo, a_hi, r_lc, a_hc):
                out.append((r_lo, a_hi, r_lc, a_hc))
        # Removal only shrinks intervals and widens gaps, so the result
        # is already disjoint, sorted, and maximal.
        self._ivs = out

    def contains(self, x):
        """Return True iff x is in the set."""
        for lo, hi, lc, hc in self._ivs:
            if lo < x < hi:
                return True
            if x == lo and lc:
                return True
            if x == hi and hc:
                return True
        return False

    def canonical(self):
        """Canonical string form: disjoint sorted maximal intervals joined
        by ' u '; points as {v}; empty set as {}."""
        if not self._ivs:
            return '{}'
        parts = []
        for lo, hi, lc, hc in self._ivs:
            if lo == hi:
                parts.append('{' + format(lo, 'g') + '}')
            else:
                parts.append(
                    ('[' if lc else '(')
                    + format(lo, 'g') + ', ' + format(hi, 'g')
                    + (']' if hc else ')')
                )
        return ' u '.join(parts)
