"""IntervalSet: maintain a set of reals as a union of intervals with open/closed endpoints."""


class IntervalSet:
    """A set of real numbers represented as a union of disjoint, maximal intervals.

    Internally the set is stored as a sorted list of canonical intervals. Each
    interval is a 4-tuple ``(lo, lo_closed, hi, hi_closed)`` where ``lo <= hi``,
    ``lo_closed``/``hi_closed`` are booleans, and a single point ``{v}`` is stored
    as ``(v, True, v, True)``. The stored list is always kept disjoint, sorted,
    and maximal (no two stored intervals overlap or touch in a way that would
    permit a merge).
    """

    def __init__(self):
        self._ivals = []

    @staticmethod
    def _mergeable(a, b):
        """Return True iff ``a`` (lower-or-equal start) can union-merge with ``b``.

        ``a`` is assumed to start no later than ``b`` in canonical sort order.
        They merge if ``a`` reaches past ``b``'s start, or if they touch at a
        shared endpoint value where at least one side includes that value.
        """
        a_lo, a_lc, a_hi, a_hc = a
        b_lo, b_lc, b_hi, b_hc = b
        if a_hi < b_lo:
            return False
        if a_hi > b_lo:
            return True
        # a_hi == b_lo: touch at a single value; merge iff either side closes it.
        return a_hc or b_lc

    @staticmethod
    def _union_pair(a, b):
        """Union two mergeable intervals; ``a`` starts no later than ``b``."""
        a_lo, a_lc, a_hi, a_hc = a
        b_lo, b_lc, b_hi, b_hc = b
        lo, lc = a_lo, a_lc
        if b_lo < lo or (b_lo == lo and b_lc and not lc):
            lo, lc = b_lo, b_lc
        if a_hi > b_hi:
            hi, hc = a_hi, a_hc
        elif b_hi > a_hi:
            hi, hc = b_hi, b_hc
        else:
            hi, hc = a_hi, (a_hc or b_hc)
        return (lo, lc, hi, hc)

    def _normalize(self, ivals):
        """Sort and merge a list of intervals into canonical form."""
        cleaned = []
        for lo, lc, hi, hc in ivals:
            if lo > hi:
                continue
            if lo == hi and not (lc and hc):
                continue
            cleaned.append((lo, lc, hi, hc))
        cleaned.sort(key=lambda iv: (iv[0], not iv[1], iv[2], not iv[3]))
        merged = []
        for iv in cleaned:
            if merged and self._mergeable(merged[-1], iv):
                merged[-1] = self._union_pair(merged[-1], iv)
            else:
                merged.append(iv)
        return merged

    def add(self, lo, hi, lo_closed, hi_closed):
        """Union the interval [lo, hi] (with given closedness) into the set."""
        if lo > hi:
            return
        if lo == hi and not (lo_closed and hi_closed):
            return
        self._ivals = self._normalize(
            self._ivals + [(lo, bool(lo_closed), hi, bool(hi_closed))]
        )

    def remove(self, lo, hi, lo_closed, hi_closed):
        """Remove (set difference) the interval [lo, hi] from the set."""
        if lo > hi:
            return
        if lo == hi and not (lo_closed and hi_closed):
            return
        r_lo, r_lc, r_hi, r_hc = lo, bool(lo_closed), hi, bool(hi_closed)
        result = []
        for a_lo, a_lc, a_hi, a_hc in self._ivals:
            # No real intersection: removal entirely left or right with no shared
            # point that both sides include.
            if r_hi < a_lo or (r_hi == a_lo and not (r_hc and a_lc)):
                result.append((a_lo, a_lc, a_hi, a_hc))
                continue
            if r_lo > a_hi or (r_lo == a_hi and not (r_lc and a_hc)):
                result.append((a_lo, a_lc, a_hi, a_hc))
                continue

            # Left remnant: part of ``a`` strictly below the removal's lower bound.
            if a_lo < r_lo:
                result.append((a_lo, a_lc, r_lo, not r_lc))
            elif a_lo == r_lo and a_lc and not r_lc:
                # a includes a_lo but removal excludes it: the point survives.
                result.append((a_lo, True, a_lo, True))

            # Right remnant: part of ``a`` strictly above the removal's upper bound.
            if a_hi > r_hi:
                result.append((r_hi, not r_hc, a_hi, a_hc))
            elif a_hi == r_hi and a_hc and not r_hc:
                # a includes a_hi but removal excludes it: the point survives.
                result.append((a_hi, True, a_hi, True))

        self._ivals = self._normalize(result)

    def contains(self, x):
        """Return True iff ``x`` is a member of the set."""
        for lo, lc, hi, hc in self._ivals:
            if x < lo or x > hi:
                continue
            if x == lo and not lc:
                continue
            if x == hi and not hc:
                continue
            return True
        return False

    def canonical(self):
        """Return the canonical string representation of the set."""
        if not self._ivals:
            return "{}"
        parts = []
        for lo, lc, hi, hc in self._ivals:
            if lo == hi:
                parts.append("{" + format(lo, "g") + "}")
            else:
                left = "[" if lc else "("
                right = "]" if hc else ")"
                parts.append(left + format(lo, "g") + ", " + format(hi, "g") + right)
        return " u ".join(parts)
