"""IntervalSet: maintain a set of real numbers as a union of intervals.

The set is stored as a sorted list of disjoint, maximal intervals.  Each
interval is a 4-tuple ``(lo, hi, lo_closed, hi_closed)`` with ``lo <= hi`` and
two booleans recording whether each endpoint is included.  A single point
``{v}`` is stored as ``(v, v, True, True)``.  The list is renormalized after
every mutation so that querying and rendering can stay simple.

Boundaries are compared via small ``(value, rank)`` keys so that ordinary tuple
comparison reproduces the ordering of points on the real line while accounting
for open/closed sides:

* a LEFT boundary closed at ``v`` sits exactly at ``v`` (rank 0); open at ``v``
  sits just after ``v`` (rank +1);
* a RIGHT boundary closed at ``v`` sits exactly at ``v`` (rank 0); open at ``v``
  sits just before ``v`` (rank -1).
"""


class IntervalSet:
    def __init__(self):
        # List of (lo, hi, lo_closed, hi_closed), kept sorted/disjoint/maximal.
        self._ivals = []

    # ------------------------------------------------------------------ #
    # Boundary-key helpers.
    # ------------------------------------------------------------------ #
    @staticmethod
    def _norm_value(v):
        # Collapse -0.0 to 0.0 so formatting and equality stay clean.
        return v + 0.0 if v == 0 else v

    @staticmethod
    def _left_key(lo, lo_closed):
        return (lo, 0 if lo_closed else 1)

    @staticmethod
    def _right_key(hi, hi_closed):
        return (hi, 0 if hi_closed else -1)

    @classmethod
    def _mergeable(cls, a, b):
        """Return True if interval ``a`` (sorted no later than ``b``) overlaps
        or touches ``b`` so that they should fuse into one maximal interval."""
        a_right = cls._right_key(a[1], a[3])
        b_left = cls._left_key(b[0], b[2])
        if b_left[0] < a_right[0]:
            return True
        if b_left[0] > a_right[0]:
            return False
        # Same value at the junction: merge unless both sides exclude it
        # (a's right open AND b's left open).
        return a[3] or b[2]

    def _normalize(self, ivals):
        """Sort, merge overlapping/touching intervals, drop empties."""
        cleaned = []
        for lo, hi, lc, hc in ivals:
            lo = self._norm_value(lo)
            hi = self._norm_value(hi)
            if lo < hi:
                cleaned.append((lo, hi, lc, hc))
            elif lo == hi and lc and hc:
                cleaned.append((lo, hi, True, True))
            # else: empty (degenerate non-point), skip
        if not cleaned:
            return []

        cleaned.sort(key=lambda iv: (self._left_key(iv[0], iv[2]),
                                     self._right_key(iv[1], iv[3])))

        merged = [cleaned[0]]
        for iv in cleaned[1:]:
            last = merged[-1]
            if self._mergeable(last, iv):
                # last starts no later than iv, so keep last's left boundary;
                # take the larger of the two right boundaries.
                if self._right_key(last[1], last[3]) >= self._right_key(iv[1], iv[3]):
                    new_hi, new_hc = last[1], last[3]
                else:
                    new_hi, new_hc = iv[1], iv[3]
                merged[-1] = (last[0], new_hi, last[2], new_hc)
            else:
                merged.append(iv)
        return merged

    # ------------------------------------------------------------------ #
    # Mutating API.
    # ------------------------------------------------------------------ #
    def add(self, lo, hi, lo_closed, hi_closed):
        if lo > hi:
            return  # defensive; spec guarantees lo <= hi
        if lo == hi and not (lo_closed and hi_closed):
            return  # empty interval, no-op
        self._ivals = self._normalize(
            self._ivals + [(lo, hi, lo_closed, hi_closed)])

    def remove(self, lo, hi, lo_closed, hi_closed):
        if lo > hi:
            return  # defensive
        if lo == hi and not (lo_closed and hi_closed):
            return  # empty removed set, no-op

        r_left = self._left_key(lo, lo_closed)
        r_right = self._right_key(hi, hi_closed)

        result = []
        for iv in self._ivals:
            result.extend(
                self._subtract(iv, lo, hi, lo_closed, hi_closed, r_left, r_right))
        self._ivals = self._normalize(result)

    def _subtract(self, iv, rlo, rhi, rlc, rhc, r_left, r_right):
        """Subtract removal region (rlo..rhi) from one stored interval ``iv``.

        Returns a list of zero, one, or two surviving interval tuples.
        """
        a_lo, a_hi, a_lc, a_hc = iv
        a_left = self._left_key(a_lo, a_lc)
        a_right = self._right_key(a_hi, a_hc)

        # No real overlap: removal ends before iv starts, or starts after iv
        # ends.  Touching at a value both sides exclude does not intersect.
        if r_right < a_left or r_left > a_right:
            return [iv]

        pieces = []

        # Left survivor: part of iv left of the removal's left boundary.
        # Exists iff iv starts strictly before the removal does.
        if a_left < r_left:
            # Complement of removal's left boundary at rlo:
            #   removal closed at rlo -> survivor open at rlo
            #   removal open at rlo   -> survivor closed at rlo
            pieces.append((a_lo, rlo, a_lc, not rlc))

        # Right survivor: part of iv right of the removal's right boundary.
        # Exists iff iv ends strictly after the removal does.
        if a_right > r_right:
            # Complement of removal's right boundary at rhi:
            #   removal closed at rhi -> survivor open at rhi
            #   removal open at rhi   -> survivor closed at rhi
            pieces.append((rhi, a_hi, not rhc, a_hc))

        return pieces

    # ------------------------------------------------------------------ #
    # Queries.
    # ------------------------------------------------------------------ #
    def contains(self, x):
        for lo, hi, lc, hc in self._ivals:
            if x < lo or x > hi:
                continue
            if x == lo:
                if lc:
                    return True
                continue
            if x == hi:
                if hc:
                    return True
                continue
            return True  # lo < x < hi
        return False

    def canonical(self):
        if not self._ivals:
            return "{}"
        parts = []
        for lo, hi, lc, hc in self._ivals:
            if lo == hi:
                parts.append("{" + format(lo, 'g') + "}")
            else:
                left = "[" if lc else "("
                right = "]" if hc else ")"
                parts.append(left + format(lo, 'g') + ", " + format(hi, 'g') + right)
        return " u ".join(parts)
