"""A module providing :class:`IntervalSet`.

An :class:`IntervalSet` represents a subset of the real line as a finite
union of intervals, where each interval endpoint may be open or closed.

Internally the set is stored as a sorted list of disjoint, maximal,
non-empty intervals.  Each interval is a 4-tuple::

    (lo, hi, lo_closed, hi_closed)

with ``lo <= hi`` (``lo == hi`` only for a single closed point, i.e. both
flags True).  The invariant that the stored list is sorted, disjoint and
maximal (no two stored intervals can be merged) is preserved after every
mutating operation, so :meth:`canonical` only needs to render the list.
"""


class IntervalSet:
    """A set of reals stored as a union of intervals with open/closed ends."""

    def __init__(self):
        # List of (lo, hi, lo_closed, hi_closed), kept sorted, disjoint, maximal.
        self._intervals = []

    # ------------------------------------------------------------------ #
    # Helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _is_empty_interval(lo, hi, lo_closed, hi_closed):
        """Return True if the described interval contains no points."""
        if lo > hi:
            return True
        if lo == hi:
            # Single point only if both endpoints are closed.
            return not (lo_closed and hi_closed)
        return False

    @staticmethod
    def _mergeable(a, b):
        """Return True if interval ``a`` (which starts <= ``b``) overlaps or
        touches ``b`` in a way that allows them to merge into one interval.

        Both ``a`` and ``b`` are non-empty, and ``a`` is sorted at or before
        ``b`` (a.lo, a.lo_closed) <= (b.lo, b.lo_closed).
        """
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b
        if a_hi > b_lo:
            # Genuine overlap of the open interiors.
            return True
        if a_hi < b_lo:
            return False
        # a_hi == b_lo: they touch at a single point. They merge iff at least
        # one side includes that shared endpoint value.
        return a_hc or b_lc

    @staticmethod
    def _union_pair(a, b):
        """Merge two mergeable intervals into one, choosing the widest bounds."""
        a_lo, a_hi, a_lc, a_hc = a
        b_lo, b_hi, b_lc, b_hc = b

        # Lower bound: smaller value wins; if equal, closed wins.
        if a_lo < b_lo:
            lo, lc = a_lo, a_lc
        elif b_lo < a_lo:
            lo, lc = b_lo, b_lc
        else:
            lo, lc = a_lo, (a_lc or b_lc)

        # Upper bound: larger value wins; if equal, closed wins.
        if a_hi > b_hi:
            hi, hc = a_hi, a_hc
        elif b_hi > a_hi:
            hi, hc = b_hi, b_hc
        else:
            hi, hc = a_hi, (a_hc or b_hc)

        return (lo, hi, lc, hc)

    def _normalize(self, intervals):
        """Sort, drop empties, and merge mergeable intervals into a canonical list."""
        clean = [
            iv for iv in intervals
            if not self._is_empty_interval(*iv)
        ]
        # Sort by lower endpoint value, then by closedness (closed first so a
        # touching closed-low comes before an open-low at the same value).
        clean.sort(key=lambda iv: (iv[0], not iv[2]))

        result = []
        for iv in clean:
            if result and self._mergeable(result[-1], iv):
                result[-1] = self._union_pair(result[-1], iv)
            else:
                result.append(iv)
        return result

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #
    def add(self, lo, hi, lo_closed, hi_closed):
        """Union the given interval into the set."""
        if self._is_empty_interval(lo, hi, lo_closed, hi_closed):
            return
        self._intervals = self._normalize(
            self._intervals + [(lo, hi, bool(lo_closed), bool(hi_closed))]
        )

    def remove(self, lo, hi, lo_closed, hi_closed):
        """Remove (set-difference) the given interval from the set."""
        if self._is_empty_interval(lo, hi, lo_closed, hi_closed):
            return

        r_lo, r_hi, r_lc, r_hc = lo, hi, bool(lo_closed), bool(hi_closed)
        new_intervals = []
        for iv in self._intervals:
            new_intervals.extend(self._subtract(iv, (r_lo, r_hi, r_lc, r_hc)))
        self._intervals = self._normalize(new_intervals)

    @staticmethod
    def _subtract(iv, rem):
        """Return a list of intervals representing ``iv`` minus ``rem``.

        ``iv`` is a non-empty stored interval; ``rem`` is a non-empty interval
        to remove.  The result is a list (0, 1 or 2 intervals).
        """
        a_lo, a_hi, a_lc, a_hc = iv
        r_lo, r_hi, r_lc, r_hc = rem

        # Determine whether the removal region actually intersects iv at all.
        # If they are completely disjoint, iv is unchanged.
        # Disjoint cases: rem entirely left of iv, or entirely right of iv.
        # rem left of iv: r_hi < a_lo, or (r_hi == a_lo and not (r_hc and a_lc))
        if r_hi < a_lo or (r_hi == a_lo and not (r_hc and a_lc)):
            return [iv]
        # rem right of iv: r_lo > a_hi, or (r_lo == a_hi and not (r_lc and a_hc))
        if r_lo > a_hi or (r_lo == a_hi and not (r_lc and a_hc)):
            return [iv]

        pieces = []

        # Left remainder: the part of iv strictly below where rem begins.
        # It exists if iv starts before rem's lower bound, considering closedness.
        if a_lo < r_lo:
            # Left piece runs from a_lo to r_lo. Its upper end is r_lo, closed
            # iff rem does NOT include r_lo (so the point r_lo stays) ... but the
            # point r_lo belongs to the left piece only if r_lo is NOT removed,
            # i.e. r_lc is False.
            left = (a_lo, r_lo, a_lc, not r_lc)
            if not IntervalSet._is_empty_interval(*left):
                pieces.append(left)
        elif a_lo == r_lo:
            # iv and rem share the lower endpoint value. The point a_lo survives
            # only if iv includes it but rem does not.
            if a_lc and not r_lc:
                point = (a_lo, a_lo, True, True)
                pieces.append(point)

        # Right remainder: the part of iv strictly above where rem ends.
        if a_hi > r_hi:
            right = (r_hi, a_hi, not r_hc, a_hc)
            if not IntervalSet._is_empty_interval(*right):
                pieces.append(right)
        elif a_hi == r_hi:
            if a_hc and not r_hc:
                point = (a_hi, a_hi, True, True)
                pieces.append(point)

        return pieces

    def contains(self, x):
        """Return True iff ``x`` is a member of the set."""
        for lo, hi, lc, hc in self._intervals:
            if lo < x < hi:
                return True
            if x == lo and lc:
                return True
            if x == hi and hc:
                return True
        return False

    def canonical(self):
        """Return the canonical string representation of the set."""
        intervals = self._normalize(self._intervals)
        if not intervals:
            return "{}"

        parts = []
        for lo, hi, lc, hc in intervals:
            if lo == hi:
                # Single point (necessarily closed on both sides).
                parts.append("{" + format(lo, "g") + "}")
            else:
                left = "[" if lc else "("
                right = "]" if hc else ")"
                parts.append(
                    left + format(lo, "g") + ", " + format(hi, "g") + right
                )
        return " u ".join(parts)
