"""IntervalSet: a set of real numbers as a union of intervals with open/closed endpoints.

Internal representation
-----------------------
A sorted list of disjoint, non-adjacent, maximal intervals. Each interval is a
4-tuple ``(lo, hi, lo_closed, hi_closed)``: floats ``lo <= hi`` plus booleans for
whether the low/high endpoints are included. A genuine single point ``{v}`` is
stored as ``(v, v, True, True)``.
"""


class IntervalSet:
    def __init__(self):
        self._ivals = []

    @staticmethod
    def _normalize(lo, hi, lo_closed, hi_closed):
        """Return a clean interval tuple, or None if the region is empty.

        Applies the degenerate rule: a zero-width region is the point {lo}
        only when both endpoints are closed, otherwise empty.
        """
        if lo > hi:
            return None
        if lo == hi:
            if lo_closed and hi_closed:
                return (lo, hi, True, True)
            return None
        return (lo, hi, bool(lo_closed), bool(hi_closed))

    @staticmethod
    def _left_key(lo, lo_closed):
        # Smaller sorts earlier; a closed low endpoint precedes an open one
        # at the same coordinate (it includes more).
        return (lo, 0 if lo_closed else 1)

    @staticmethod
    def _right_key(hi, hi_closed):
        # Larger sorts later; a closed high endpoint extends past an open one
        # at the same coordinate.
        return (hi, 1 if hi_closed else 0)

    @classmethod
    def _mergeable(cls, a, b):
        """True iff a and b overlap OR touch at a shared endpoint included by
        at least one side (so their union is a single interval)."""
        alo, ahi, alc, ahc = a
        blo, bhi, blc, bhc = b
        if cls._left_key(alo, alc) > cls._left_key(blo, blc):
            alo, ahi, alc, ahc, blo, bhi, blc, bhc = blo, bhi, blc, bhc, alo, ahi, alc, ahc
        # a is the left-most interval; check whether b starts before a ends.
        if ahi < blo:
            return False
        if ahi > blo:
            return True
        return ahc or blc

    @classmethod
    def _union_two(cls, a, b):
        alo, ahi, alc, ahc = a
        blo, bhi, blc, bhc = b
        if cls._left_key(alo, alc) <= cls._left_key(blo, blc):
            lo, lc = alo, alc
        else:
            lo, lc = blo, blc
        if cls._right_key(ahi, ahc) >= cls._right_key(bhi, bhc):
            hi, hc = ahi, ahc
        else:
            hi, hc = bhi, bhc
        return (lo, hi, lc, hc)

    def add(self, lo, hi, lo_closed, hi_closed):
        new = self._normalize(lo, hi, lo_closed, hi_closed)
        if new is None:
            return
        merged = []
        inserted = False
        cur = new
        for iv in self._ivals:
            if self._mergeable(cur, iv):
                cur = self._union_two(cur, iv)
            elif self._left_key(iv[0], iv[2]) < self._left_key(cur[0], cur[2]):
                merged.append(iv)
            else:
                if not inserted:
                    merged.append(cur)
                    inserted = True
                merged.append(iv)
        if not inserted:
            merged.append(cur)
        self._ivals = merged

    def remove(self, lo, hi, lo_closed, hi_closed):
        cut = self._normalize(lo, hi, lo_closed, hi_closed)
        if cut is None:
            return
        clo, chi, clc, chc = cut
        result = []
        for iv in self._ivals:
            result.extend(self._subtract_one(iv, clo, chi, clc, chc))
        self._ivals = result

    @classmethod
    def _subtract_one(cls, iv, clo, chi, clc, chc):
        """Subtract region (clo, chi, clc, chc) from interval iv; return the
        0, 1, or 2 surviving pieces."""
        ilo, ihi, ilc, ihc = iv
        # No real value in common: region lies entirely past one end of iv.
        if ihi < clo or (ihi == clo and not (ihc and clc)):
            return [iv]
        if chi < ilo or (chi == ilo and not (chc and ilc)):
            return [iv]
        out = []
        # Left survivor: iv extends left of the cut's low boundary.
        if cls._left_key(ilo, ilc) < cls._left_key(clo, clc):
            piece = cls._normalize(ilo, clo, ilc, not clc)
            if piece is not None:
                out.append(piece)
        # Right survivor: iv extends right of the cut's high boundary.
        if cls._right_key(ihi, ihc) > cls._right_key(chi, chc):
            piece = cls._normalize(chi, ihi, not chc, ihc)
            if piece is not None:
                out.append(piece)
        return out

    def contains(self, x):
        for ilo, ihi, ilc, ihc in self._ivals:
            if x < ilo or x > ihi:
                continue
            if x == ilo and not ilc:
                continue
            if x == ihi and not ihc:
                continue
            return True
        return False

    def canonical(self):
        if not self._ivals:
            return "{}"
        parts = []
        for ilo, ihi, ilc, ihc in self._ivals:
            if ilo == ihi:
                parts.append("{" + format(ilo, "g") + "}")
            else:
                left = "[" if ilc else "("
                right = "]" if ihc else ")"
                parts.append(left + format(ilo, "g") + ", " + format(ihi, "g") + right)
        return " u ".join(parts)
