class IntervalSet:
    """Maintain a set of reals as a union of intervals with open/closed endpoints.

    Internal representation:
        self._ivs is a list of tuples (lo, lc, hi, hc) where
            lo, hi  : float endpoint values (lo <= hi)
            lc, hc  : booleans, whether the low/high endpoint is included
        The list is kept canonical: sorted ascending, disjoint, and maximal
        (no two stored intervals can be merged). Single points are stored as
        (v, True, v, True).
    """

    def __init__(self):
        self._ivs = []

    # ---------------------------------------------------------------- helpers

    @staticmethod
    def _is_empty_piece(lo, hi, lo_closed, hi_closed):
        """An interval describes the empty set when lo > hi, or lo == hi but
        it is not the fully-closed single point."""
        if lo > hi:
            return True
        if lo == hi and not (lo_closed and hi_closed):
            return True
        return False

    @staticmethod
    def _touch_or_overlap(a, b):
        """Given two intervals a, b each (lo, lc, hi, hc) with a sorting before
        or equal to b by start, decide whether their union is a single interval,
        i.e. they overlap OR touch at a shared endpoint included by at least one
        side. Assumes a starts at or before b."""
        a_lo, a_lc, a_hi, a_hc = a
        b_lo, b_lc, b_hi, b_hc = b
        # They are separate if a ends strictly before b starts.
        if a_hi < b_lo:
            return False
        if a_hi > b_lo:
            return True  # genuine overlap on values
        # a_hi == b_lo : they touch at this single value; merge iff at least one
        # side includes it.
        return a_hc or b_lc

    @staticmethod
    def _union_pair(a, b):
        """Union of two intervals known to overlap/touch-merge. Returns the
        combined (lo, lc, hi, hc)."""
        a_lo, a_lc, a_hi, a_hc = a
        b_lo, b_lc, b_hi, b_hc = b
        # low endpoint
        if a_lo < b_lo:
            lo, lc = a_lo, a_lc
        elif b_lo < a_lo:
            lo, lc = b_lo, b_lc
        else:
            lo, lc = a_lo, (a_lc or b_lc)
        # high endpoint
        if a_hi > b_hi:
            hi, hc = a_hi, a_hc
        elif b_hi > a_hi:
            hi, hc = b_hi, b_hc
        else:
            hi, hc = a_hi, (a_hc or b_hc)
        return (lo, lc, hi, hc)

    def _normalize(self, pieces):
        """Take an arbitrary list of (lo, lc, hi, hc) pieces and produce the
        canonical sorted, disjoint, maximal list."""
        pieces = [p for p in pieces
                  if not self._is_empty_piece(p[0], p[2], p[1], p[3])]
        if not pieces:
            return []
        # sort by start point (value, then closed-before-open)
        pieces.sort(key=lambda p: (p[0], 0 if p[1] else 1))
        merged = [pieces[0]]
        for p in pieces[1:]:
            last = merged[-1]
            if self._touch_or_overlap(last, p):
                merged[-1] = self._union_pair(last, p)
            else:
                merged.append(p)
        return merged

    # ---------------------------------------------------------------- API

    def add(self, lo, hi, lo_closed, hi_closed):
        lo = float(lo)
        hi = float(hi)
        lo_closed = bool(lo_closed)
        hi_closed = bool(hi_closed)
        if self._is_empty_piece(lo, hi, lo_closed, hi_closed):
            return  # no-op for empty/degenerate
        self._ivs = self._normalize(self._ivs + [(lo, lo_closed, hi, hi_closed)])

    def remove(self, lo, hi, lo_closed, hi_closed):
        lo = float(lo)
        hi = float(hi)
        lo_closed = bool(lo_closed)
        hi_closed = bool(hi_closed)
        if self._is_empty_piece(lo, hi, lo_closed, hi_closed):
            return  # removing nothing
        r_lo, r_lc, r_hi, r_hc = lo, lo_closed, hi, hi_closed
        result = []
        for a_lo, a_lc, a_hi, a_hc in self._ivs:
            result.extend(
                self._subtract_one(a_lo, a_lc, a_hi, a_hc,
                                   r_lo, r_lc, r_hi, r_hc)
            )
        self._ivs = self._normalize(result)

    def _subtract_one(self, a_lo, a_lc, a_hi, a_hc, r_lo, r_lc, r_hi, r_hc):
        """Subtract removal interval r from stored interval a. Returns a list of
        0, 1, or 2 surviving pieces."""
        # r entirely to the left of a (touching value not in BOTH removes nothing)
        if r_hi < a_lo or (r_hi == a_lo and not (r_hc and a_lc)):
            return [(a_lo, a_lc, a_hi, a_hc)]
        # r entirely to the right of a
        if r_lo > a_hi or (r_lo == a_hi and not (r_lc and a_hc)):
            return [(a_lo, a_lc, a_hi, a_hc)]

        pieces = []

        # Left surviving piece: part of a strictly left of r's start.
        if a_lo < r_lo:
            # new high endpoint is r_lo; included iff r does NOT include r_lo.
            pieces.append((a_lo, a_lc, r_lo, not r_lc))
        elif a_lo == r_lo:
            # point {a_lo} survives iff a includes it but r does not.
            if a_lc and not r_lc:
                pieces.append((a_lo, True, a_lo, True))

        # Right surviving piece: part of a strictly right of r's end.
        if a_hi > r_hi:
            pieces.append((r_hi, not r_hc, a_hi, a_hc))
        elif a_hi == r_hi:
            if a_hc and not r_hc:
                pieces.append((a_hi, True, a_hi, True))

        pieces = [p for p in pieces
                  if not self._is_empty_piece(p[0], p[2], p[1], p[3])]
        return pieces

    def contains(self, x):
        for lo, lc, hi, hc in self._ivs:
            if lo < x < hi:
                return True
            if x == lo and lc:
                return True
            if x == hi and hc:
                return True
        return False

    def canonical(self):
        if not self._ivs:
            return "{}"
        parts = []
        for lo, lc, hi, hc in self._ivs:
            if lo == hi:
                parts.append("{" + format(lo, 'g') + "}")
            else:
                left = "[" if lc else "("
                right = "]" if hc else ")"
                parts.append(left + format(lo, 'g') + ", " + format(hi, 'g') + right)
        return " u ".join(parts)
